/* FRAME/12 Design System — Tokens, Panel Grammar, Screentone, and Motion on Twos.
   Works standalone without Tailwind. All rules are scoped to .f12-* classes. */

/* @tokens:start */
/* Generated by @frame12/tokens — generated, do not edit by hand. */
/* Cross-platform metric-matched fallbacks for Dela Gothic One, Zen Kaku Gothic New, and
   M PLUS 1 Code across macOS, Windows, Linux (Liberation/DejaVu/Noto), and Android (Roboto)
   so cold-network .woff2 swaps do not reflow headings, controls, paragraphs, or tables. */
@font-face {
  font-family: "f12DisplayFallback";
  src: local("Arial"), local("Helvetica Neue"), local("Helvetica"), local("Liberation Sans"), local("Arimo"), local("Nimbus Sans"), local("Nimbus Sans L"), local("Roboto"), local("Noto Sans"), local("FreeSans");
  font-weight: 400;
  size-adjust: 131.74%;
  ascent-override: 88.05%;
  descent-override: 21.86%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "f12DisplayFallbackDejaVu";
  src: local("DejaVu Sans"), local("Bitstream Vera Sans"), local("Verdana");
  font-weight: 400;
  size-adjust: 120.3%;
  ascent-override: 96.4%;
  descent-override: 23.9%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "f12BodyFallback";
  src: local("Arial"), local("Helvetica Neue"), local("Helvetica"), local("Liberation Sans"), local("Arimo"), local("Nimbus Sans"), local("Nimbus Sans L"), local("Roboto"), local("Noto Sans"), local("FreeSans");
  font-weight: 400;
  size-adjust: 99.1%;
  ascent-override: 117.05%;
  descent-override: 29.06%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "f12BodyFallbackDejaVu";
  src: local("DejaVu Sans"), local("Bitstream Vera Sans"), local("Verdana");
  font-weight: 400;
  size-adjust: 90.5%;
  ascent-override: 128.17%;
  descent-override: 31.82%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "f12MonoFallbackConsolas";
  src: local("Consolas");
  font-weight: 400;
  size-adjust: 90.91%;
  ascent-override: 110%;
  descent-override: 25.85%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "f12MonoFallback";
  src: local("Menlo"), local("DejaVu Sans Mono"), local("Courier New"), local("Liberation Mono"), local("Cousine"), local("Noto Sans Mono"), local("Droid Sans Mono");
  font-weight: 400;
  size-adjust: 83.19%;
  ascent-override: 120.21%;
  descent-override: 28.25%;
  line-gap-override: 0%;
}

:where(:root) {
  --font-f-display: var(--font-dela-gothic-one, "Dela Gothic One"), "f12DisplayFallback", "f12DisplayFallbackDejaVu", "Arial Black", "Helvetica Neue", sans-serif;
  --font-f-body: var(--font-zen-kaku-gothic-new, "Zen Kaku Gothic New"), "f12BodyFallback", "f12BodyFallbackDejaVu", "Hiragino Sans", "Helvetica Neue", "Arial", sans-serif;
  --font-f-mono: var(--font-m-plus-1-code, "M PLUS 1 Code"), "f12MonoFallbackConsolas", "f12MonoFallback", ui-monospace, "SF Mono", "Menlo", monospace;

  --f-gutter-pair: 12px;
  --f-gutter-scene: 20px;
  --f-gutter-change: 32px;

  --f-stroke: 2.5px;
  --f-pose: 83.33ms;
  --f-fps: 12;

  --f-shadow-sheet: 0 1px 0 rgba(0, 0, 0, 0.05), 0 18px 40px -26px rgba(0, 0, 0, 0.5);
  --f-shadow-peg: inset 0 1px 2px rgba(0, 0, 0, 0.25);
  --f-backdrop: rgba(12, 12, 12, 0.78);
  --f-diff: #ffffff;
}

:where(:root),
:root[data-theme="light"],
.f12-theme-light {
  --f-desk: #e2e3e5;
  --f-sheet: #ffffff;
  --f-panel: #ffffff;
  --f-ink: #121212;
  --f-ink-2: #4b4b4b;
  --f-rule: #121212;
  --f-tone: #121212;
  --f-grid: #e3e3e3;
  --f-marker: #ffd60a;
  --f-marker-ink: #121212;
  --f-hole: #e2e3e5;
  color-scheme: light;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]):not(.f12-theme-light) {
    --f-desk: #000000;
    --f-sheet: #050505;
    --f-panel: #19191a;
    --f-ink: #f1f0ea;
    --f-ink-2: #b9b8b1;
    --f-rule: #f1f0ea;
    --f-tone: #f1f0ea;
    --f-grid: #2c2c2d;
    --f-marker: #ffd60a;
    --f-marker-ink: #121212;
    --f-hole: #000000;
    color-scheme: dark;
  }
}

:root[data-theme="dark"],
.f12-theme-dark {
  --f-desk: #000000;
  --f-sheet: #050505;
  --f-panel: #19191a;
  --f-ink: #f1f0ea;
  --f-ink-2: #b9b8b1;
  --f-rule: #f1f0ea;
  --f-tone: #f1f0ea;
  --f-grid: #2c2c2d;
  --f-marker: #ffd60a;
  --f-marker-ink: #121212;
  --f-hole: #000000;
  color-scheme: dark;
}
/* @tokens:end */

/* ===================================================================== Scoped Base & Reset */
.f12-dash,
.f12-sheet,
.f12-scene,
.f12-panel,
.f12-pair,
.f12-rng,
.f12-metric,
.f12-chart,
.f12-ints,
.f12-btn,
.f12-field,
.f12-input,
.f12-textarea,
.f12-check-field,
.f12-checkbox-control,
.f12-checkbox-input,
.f12-radio-group,
.f12-radio-item,
.f12-radio-control,
.f12-radio-input,
.f12-switch,
.f12-switch-input,
.f12-switch-track,
.f12-switch-thumb,
.f12-tabs,
.f12-tabs-list,
.f12-tabs-trigger,
.f12-tabs-content,
.f12-dialog,
.f12-select,
.f12-select-content,
.f12-tooltip-wrap,
.f12-menu-wrap,
.f12-menu,
.f12-table-wrap,
.f12-balloon,
.f12-balloon-standalone,
.f12-tag,
.f12-badge,
.f12-ghost-wire,
.f12-receipt,
.f12-receipt-list {
  box-sizing: border-box;
}

.f12-dash *,
.f12-dash *::before,
.f12-dash *::after,
.f12-sheet *,
.f12-sheet *::before,
.f12-sheet *::after,
.f12-panel *,
.f12-panel *::before,
.f12-panel *::after,
.f12-field *,
.f12-check-field *,
.f12-radio-group *,
.f12-tabs *,
.f12-dialog *,
.f12-select *,
.f12-select-content *,
.f12-menu *,
.f12-table-wrap *,
.f12-ghost-wire *,
.f12-receipt *,
.f12-receipt-list * {
  box-sizing: border-box;
}

.f12-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
  user-select: none;
  -webkit-user-select: none;
}

:where(.f12-frame button, .f12-sheet button, .f12-dialog button, button[class*="f12-"]) {
  font: inherit;
  color: inherit;
}

.f12-frame :focus-visible,
.f12-sheet :focus-visible,
.f12-dialog :focus-visible,
[class*="f12-"]:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}

/* ===================================================================== Sheet & Pegs */
.f12-dash {
  container-type: inline-size;
  position: relative;
}
.f12-dash :where(h2, h3, p, ul) {
  margin: 0;
}
.f12-dash :where(ul) {
  list-style: none;
  padding: 0;
}

.f12-frame {
  background: var(--f-desk);
  color: var(--f-ink);
  font-family: var(--font-f-body);
  padding: 20px;
  border-radius: 4px;
}

.f12-sheet {
  position: relative;
  background: var(--f-sheet);
  color: var(--f-ink);
  font-family: var(--font-f-body);
  padding: 44px 28px 28px;
  display: flex;
  flex-direction: column;
  gap: var(--f-gutter-change); /* 32px = scene change */
  box-shadow: var(--f-shadow-sheet);
  counter-reset: f12-cut;
}

.f12-pegs {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 26px;
  align-items: center;
}
.f12-peg {
  display: block;
  background: var(--f-hole);
  border: 1px solid var(--f-grid);
  box-shadow: var(--f-shadow-peg);
}
.f12-peg.round {
  width: 11px;
  height: 11px;
  border-radius: 50%;
}
.f12-peg.slot {
  width: 26px;
  height: 8px;
  border-radius: 4px;
}

.f12-hd {
  display: flex;
  flex-wrap: wrap;
  gap: 16px 24px;
  align-items: flex-end;
  justify-content: space-between;
}
/* Let the text column shrink below its longest unbreakable token so long titles/IDs wrap (or,
   failing that, overflow inside the sheet) instead of widening the page on narrow screens. */
.f12-hd > .f12-hd-text {
  min-width: 0;
}
.f12-eyebrow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
/* Eyebrow chips (file paths, IDs) may be one unbreakable token: let them shrink and break
   rather than push a narrow sheet wider than the viewport. */
.f12-eyebrow > :is(.f12-tag, .f12-badge) {
  min-width: 0;
  overflow-wrap: anywhere;
}
.f12-title {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: clamp(30px, 5.2cqi, 46px);
  line-height: 1.02;
  margin-top: 10px;
  letter-spacing: 0.005em;
  text-wrap: balance;
}
/* Programmatic focus target only (e.g. after a breadcrumb steps up a level); not operable, so
   no ring — the heading itself is the visible landmark. */
.f12-title[tabindex='-1']:focus {
  outline: none;
}
.f12-sub {
  font-family: var(--font-f-mono);
  font-size: 12px;
  color: var(--f-ink-2);
  margin-top: 8px;
  letter-spacing: 0.04em;
}

/* ===================================================================== Scene & Gutter Grammar
   12px = pair, 20px = same scene, 32px = scene change */
.f12-scene {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
  gap: var(--f-gutter-scene);
  min-width: 0;
}
.f12-scene.f12-scene-split {
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
}
.f12-scene.f12-scene-stack {
  grid-template-columns: minmax(0, 1fr);
}
.f12-scene.f12-scene-equal {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.f12-scene.f12-scene-three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.f12-scene.f12-scene-areas {
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: none;
}
.f12-scene.f12-scene-areas > [data-area],
.f12-scene-area {
  min-width: 0;
  grid-area: auto;
}
.f12-scene-area {
  display: flex;
  flex-direction: column;
}
.f12-scene-area > .f12-panel {
  flex: 1;
}
@media (min-width: 860px) {
  .f12-scene.f12-scene-areas:not([data-scene-bp]) {
    grid-template-columns: repeat(var(--f12-scene-cols, 12), minmax(0, 1fr));
    grid-template-areas: var(--f12-scene-areas);
  }
  .f12-scene.f12-scene-areas:not([data-scene-bp]) > [data-area] {
    grid-area: var(--f12-area);
  }
}
.f12-scene.f12-scene-pair {
  gap: var(--f-gutter-pair);
}
.f12-scene.f12-scene-scene {
  gap: var(--f-gutter-scene);
}
.f12-scene.f12-scene-change {
  gap: var(--f-gutter-change);
}

.f12-pair {
  display: flex;
  flex-direction: column;
  gap: var(--f-gutter-pair);
  min-width: 0;
}
.f12-pair > .f12-panel {
  flex: 1;
}

/* ===================================================================== Panel */
.f12-panel {
  position: relative;
  min-width: 0;
  display: flex;
  flex-direction: column;
  color: var(--f-ink);
  font-family: var(--font-f-body);
}
.f12-panel-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}
.f12-panel-frame polygon {
  fill: var(--f-panel);
  stroke: var(--f-rule);
  stroke-width: var(--f-stroke);
  stroke-linejoin: miter;
}
.f12-panel-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  position: relative;
  padding: 24px 22px 22px;
}
.f12-panel.f12-slant-bottom > .f12-panel-body {
  padding-bottom: 36px;
}
.f12-panel.f12-slant-top > .f12-panel-body {
  padding-top: 36px;
}
.f12-cut {
  position: absolute;
  top: -8px;
  left: 16px;
  z-index: 1;
  padding: 0 6px;
  line-height: 16px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.12em;
  background: var(--f-sheet);
  color: var(--f-ink);
}
/* <Sheet autoCut> also sets --f12-autocut-display inline; this attribute rule keeps cut labels
   numbered where a strict CSP blocks inline style attributes (static pages in webviews). */
.f12-sheet[data-autocut] {
  --f12-autocut-display: block;
}
.f12-cut[data-autocut] {
  display: var(--f12-autocut-display, none);
  counter-increment: f12-cut;
}
.f12-cut[data-autocut]::before {
  content: "C-" counter(f12-cut, decimal-leading-zero);
}
.f12-panel.f12-slant-top > .f12-cut {
  top: 8px;
}
.f12-panel.f12-panel-quiet {
  background: var(--f-panel);
  border: 1px solid var(--f-rule);
}
.f12-panel.f12-panel-quiet:not(.f12-rect) {
  background: none;
  border: 0;
}
.f12-panel.f12-panel-quiet > .f12-panel-frame > polygon {
  stroke-width: 1;
}
.f12-panel.f12-panel-quiet > .f12-panel-body {
  padding: 16px 18px;
}
.f12-panel.f12-panel-quiet.f12-slant-bottom > .f12-panel-body {
  padding-bottom: 32px;
}
.f12-panel.f12-panel-quiet.f12-slant-top > .f12-panel-body {
  padding-top: 32px;
}

/* ===================================================================== Tag & Badge */
.f12-tag {
  position: relative;
  display: inline-block;
  vertical-align: middle;
  max-width: 100%;
  overflow-wrap: break-word;
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-marker-ink);
  background: var(--f-marker);
  padding: 1px 6px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.f12-tag-stamp {
  font-family: var(--font-f-display);
  font-size: 11px;
  font-weight: 400;
  line-height: 1.25;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 2px 8px;
  border: 2px solid var(--f-rule);
  background: var(--f-panel);
  color: var(--f-ink);
  transform: rotate(-3deg);
  transform-origin: center;
}

.f12-badge {
  position: relative;
  display: inline-block;
  vertical-align: middle;
  max-width: 100%;
  overflow-wrap: break-word;
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 2px 7px;
  background: var(--f-marker);
  color: var(--f-marker-ink);
  border: 2px solid var(--f-rule);
}
.f12-badge-t {
  position: relative;
  z-index: 1;
}
.f12-tag svg,
.f12-badge-t svg {
  display: inline-block;
  vertical-align: middle;
  margin-inline-end: 4px;
}
.f12-status-glyph {
  margin-inline-end: 4px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
  user-select: none;
  -webkit-user-select: none;
}
.f12-status-neutral {
  background: var(--f-panel);
  color: var(--f-ink);
  border: 1px solid var(--f-rule);
}
.f12-status-info {
  background: var(--f-panel);
  color: var(--f-ink);
  border: 1.5px solid var(--f-rule);
}
.f12-status-success {
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  border-inline-start: 5px solid var(--f-rule);
  font-weight: 700;
}
.f12-status-warning {
  background-color: var(--f-panel);
  background-image: repeating-linear-gradient(
    -45deg,
    transparent 0 5px,
    var(--f-grid) 5px 6.5px
  );
  color: var(--f-ink);
  border: 2px dashed var(--f-rule);
  font-weight: 700;
}
.f12-status-warning .f12-status-glyph {
  color: var(--f-ink);
}
.f12-status-danger {
  background: var(--f-ink);
  color: var(--f-panel);
  border: 2px solid var(--f-rule);
  box-shadow: inset 0 0 0 1.5px var(--f-panel);
  font-weight: 700;
}
.f12-status-danger .f12-status-glyph {
  color: var(--f-panel);
}
.f12-tag-stamp.f12-status-neutral,
.f12-tag-stamp.f12-status-info {
  border-width: 2px;
}
.f12-tag-stamp.f12-status-success,
.f12-tag-stamp.f12-status-warning,
.f12-tag-stamp.f12-status-danger {
  font-weight: 400;
}

/* ===================================================================== GhostWire & Receipt */
.f12-ghost-wire {
  display: grid;
  grid-template-columns: minmax(0, max-content) minmax(24px, 1fr) minmax(0, max-content);
  align-items: center;
  gap: var(--f-gutter-pair);
  min-width: 0;
  max-width: 100%;
  color: var(--f-ink);
  font-family: var(--font-f-mono);
}
.f12-ghost-wire.f12-ghost-wire-vertical,
.f12-ghost-wire[data-orientation="vertical"] {
  grid-template-columns: minmax(0, 1fr);
  justify-items: start;
}
.f12-ghost-wire-endpoint {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
  padding: 4px 10px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  line-height: 1.35;
  color: var(--f-ink);
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-ghost-wire-from {
  border: 2px solid var(--f-rule);
  background: var(--f-panel);
  font-weight: 700;
}
.f12-ghost-wire-to {
  border: 2px dashed var(--f-rule);
  background: var(--f-sheet);
  font-weight: 500;
}
.f12-ghost-wire-connector {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 24px;
  width: 100%;
}
.f12-ghost-wire.f12-ghost-wire-vertical .f12-ghost-wire-connector,
.f12-ghost-wire[data-orientation="vertical"] .f12-ghost-wire-connector {
  flex-direction: row;
  justify-content: flex-start;
  min-width: 0;
  width: auto;
  padding-inline-start: 14px;
}
.f12-ghost-wire-svg {
  display: block;
  width: 100%;
  height: 12px;
  overflow: visible;
  flex-shrink: 0;
}
.f12-ghost-wire.f12-ghost-wire-vertical .f12-ghost-wire-svg,
.f12-ghost-wire[data-orientation="vertical"] .f12-ghost-wire-svg {
  width: 12px;
  height: 28px;
}
.f12-ghost-wire-line {
  stroke: var(--f-rule);
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
  fill: none;
}
.f12-ghost-wire-reveal {
  stroke: #fff;
  stroke-width: 12;
  fill: none;
}
.f12-ghost-wire-label {
  font-family: var(--font-f-mono);
  font-size: 11px;
  line-height: 1.3;
  color: var(--f-ink-2);
  text-align: center;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-ghost-wire.f12-ghost-wire-vertical .f12-ghost-wire-label,
.f12-ghost-wire[data-orientation="vertical"] .f12-ghost-wire-label {
  text-align: start;
}

.f12-receipt-list {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--f-gutter-pair);
  list-style: none;
  margin: 0;
  padding: 0;
  min-width: 0;
  max-width: 100%;
}
.f12-receipt-item {
  min-width: 0;
  max-width: 100%;
  display: inline-flex;
}
.f12-receipt {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
  padding: 3px 8px;
  border: 1.5px solid var(--f-rule);
  background: var(--f-panel);
  color: var(--f-ink);
  font-family: var(--font-f-body);
  font-size: 12px;
  line-height: 1.4;
}
.f12-receipt-origin {
  display: inline-flex;
  align-items: center;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  color: var(--f-ink);
}
.f12-receipt-origin .f12-status-glyph {
  margin-inline-end: 0;
}
.f12-receipt-value {
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 700;
  color: var(--f-ink);
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-receipt-code {
  font-family: inherit;
  font-size: inherit;
  font-weight: inherit;
  color: inherit;
  background: none;
  padding: 0;
}
.f12-receipt-link {
  color: var(--f-ink);
  text-decoration: underline;
  text-decoration-thickness: 1.5px;
  text-underline-offset: 2px;
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-receipt-link:hover {
  background: var(--f-marker);
  color: var(--f-marker-ink);
}
.f12-receipt-title {
  font-family: var(--font-f-body);
  font-size: 12px;
  color: var(--f-ink);
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-receipt-date {
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink-2);
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-burst {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 150%;
  height: auto;
  transform: translate(-50%, -50%);
  opacity: 0;
  pointer-events: none;
}
.f12-burst line {
  stroke: var(--f-ink);
  stroke-width: 2;
  stroke-linecap: square;
}

/* ===================================================================== SegmentedControl (RangeTabs) */
.f12-rng {
  position: relative;
  display: inline-flex;
  flex: none;
  isolation: isolate;
  border: var(--f-stroke) solid var(--f-rule);
  background: var(--f-panel);
}
.f12-rng-ind {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  background: var(--f-diff);
  mix-blend-mode: difference;
  pointer-events: none;
}
.f12-rng-btn {
  cursor: pointer;
  background: none;
  border: 0;
  display: grid;
  justify-items: center;
  padding: 6px 16px 5px;
  color: var(--f-ink);
  min-width: 64px;
}
.f12-rng-btn + .f12-rng-btn {
  border-left: 2px solid var(--f-rule);
}
.f12-rng:not(:has(.f12-rng-ind)) .f12-rng-btn[aria-pressed="true"] {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-rng-n {
  font-family: var(--font-f-display);
  font-size: 18px;
  line-height: 1;
}
.f12-rng-u {
  font-family: var(--font-f-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.f12-rng-btn:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: -6px;
}
.f12-rng:not(:has(.f12-rng-ind)) .f12-rng-btn[aria-pressed="true"]:focus-visible {
  outline-color: currentColor;
}

/* ===================================================================== Tempo Control
   Native radios in the segmented appearance (.f12-rng / .f12-rng-btn). No indicator slide:
   the control that sets motion does not itself move. */
.f12-tempo {
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
  display: grid;
  gap: 4px;
  justify-items: start;
}
.f12-tempo-legend {
  padding: 0;
  margin-bottom: 4px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink);
}
.f12-tempo .f12-tempo-opt {
  position: relative;
  min-width: 44px;
  min-height: 44px;
  align-content: center;
  padding: 6px 10px 5px;
}
.f12-tempo-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: inherit;
}
.f12-tempo-opt:has(.f12-tempo-input:checked) {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-tempo-opt:has(.f12-tempo-input:focus-visible) {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
  z-index: 1;
}
.f12-tempo:disabled .f12-tempo-opt {
  cursor: not-allowed;
  opacity: 0.55;
}
.f12-tempo-note-reduced {
  display: none;
}
@media (prefers-reduced-motion: reduce) {
  .f12-tempo-note-reduced {
    display: block;
  }
}
.f12-tempo-note {
  margin: 0;
  max-width: 32ch;
  font-family: var(--font-f-mono);
  font-size: 11px;
  line-height: 1.4;
  color: var(--f-ink);
}

/* ===================================================================== Button & Input */
.f12-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  font-family: var(--font-f-mono);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: var(--f-stroke) solid var(--f-rule);
  background: var(--f-panel);
  color: var(--f-ink);
  padding: 8px 16px;
  font-size: 12px;
  line-height: 1.2;
}
.f12-btn-sm {
  padding: 5px 10px;
  font-size: 11px;
}
.f12-btn-md {
  padding: 8px 16px;
  font-size: 12px;
}
.f12-btn-lg {
  padding: 12px 22px;
  font-size: 13px;
}
.f12-btn-primary {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-btn-secondary {
  background: var(--f-panel);
  color: var(--f-ink);
}
.f12-btn-marker {
  background: var(--f-marker);
  color: var(--f-marker-ink);
}
.f12-btn:hover:not(:disabled) {
  box-shadow: 3px 3px 0 var(--f-rule);
}
.f12-btn:active:not(:disabled) {
  box-shadow: none;
}
.f12-btn:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-btn:disabled {
  cursor: not-allowed;
  border-style: dashed;
  color: var(--f-ink-2);
  background: var(--f-panel);
}

.f12-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-family: var(--font-f-body);
  color: var(--f-ink);
}
.f12-label {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.f12-field-req {
  color: var(--f-ink);
  font-weight: 700;
}
.f12-input {
  width: 100%;
  padding: 9px 12px;
  font-family: var(--font-f-body);
  font-size: 14px;
  line-height: 1.4;
  color: var(--f-ink);
  background: var(--f-panel);
  border: var(--f-stroke) solid var(--f-rule);
  border-radius: 0;
}
.f12-input::placeholder {
  color: var(--f-ink-2);
}
.f12-input:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-input:disabled {
  cursor: not-allowed;
  border-style: dashed;
  color: var(--f-ink-2);
  background: var(--f-panel);
}
.f12-field.f12-field-compact {
  gap: 4px;
}
.f12-input.f12-input-compact {
  padding: 6px 10px;
  font-size: 13px;
  border-width: 1.5px;
}
.f12-textarea {
  width: 100%;
  min-height: 84px;
  padding: 9px 12px;
  font-family: var(--font-f-body);
  font-size: 14px;
  line-height: 1.45;
  color: var(--f-ink);
  background: var(--f-panel);
  border: var(--f-stroke) solid var(--f-rule);
  border-radius: 0;
  resize: vertical;
}
.f12-textarea::placeholder {
  color: var(--f-ink-2);
}
.f12-textarea:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-textarea:disabled {
  cursor: not-allowed;
  border-style: dashed;
  color: var(--f-ink-2);
  background: var(--f-panel);
}
.f12-textarea.f12-textarea-compact {
  min-height: 68px;
  padding: 6px 10px;
  font-size: 13px;
  line-height: 1.4;
  border-width: 1.5px;
}
.f12-hint {
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink-2);
  margin: 0;
}
.f12-error {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink);
  margin: 0;
}
.f12-error-flag {
  background: var(--f-marker);
  color: var(--f-marker-ink);
  padding: 0 4px;
  font-weight: 700;
}

/* ===================================================================== Checkbox, RadioGroup, Switch & Tabs */
.f12-check-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-family: var(--font-f-body);
  color: var(--f-ink);
}
.f12-check-row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.f12-check-label {
  font-family: var(--font-f-body);
  font-size: 14px;
  line-height: 1.4;
  color: var(--f-ink);
  cursor: pointer;
  user-select: none;
}
.f12-check-field-compact .f12-check-label,
.f12-field-compact .f12-check-label,
.f12-radio-item-compact .f12-check-label {
  font-size: 13px;
}
[data-disabled] .f12-check-label {
  color: var(--f-ink-2);
  cursor: not-allowed;
}
.f12-check-meta {
  padding-inline-start: 34px;
}

.f12-checkbox-control,
.f12-radio-control {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  flex: none;
}
.f12-checkbox-input,
.f12-radio-input {
  -webkit-appearance: none;
  appearance: none;
  margin: 0;
  width: 24px;
  height: 24px;
  background: var(--f-panel);
  border: var(--f-stroke) solid var(--f-rule);
  cursor: pointer;
  display: block;
}
.f12-checkbox-input {
  border-radius: 0;
}
.f12-radio-input {
  border-radius: 50%;
}
.f12-checkbox-input.f12-checkbox-compact,
.f12-radio-input.f12-radio-compact {
  border-width: 1.5px;
}
.f12-checkbox-input:focus-visible,
.f12-radio-input:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-checkbox-input:disabled,
.f12-radio-input:disabled {
  cursor: not-allowed;
  border-style: dashed;
  opacity: 0.6;
}
.f12-checkbox-input:checked,
.f12-checkbox-input:indeterminate,
.f12-checkbox-input.f12-checkbox-indeterminate,
.f12-checkbox-input[data-indeterminate="true"] {
  background: var(--f-ink);
}
.f12-checkbox-mark,
.f12-radio-mark {
  position: absolute;
  inset: 0;
  width: 16px;
  height: 16px;
  margin: auto;
  pointer-events: none;
  opacity: 0;
}
.f12-checkbox-mark {
  color: var(--f-panel);
}
.f12-radio-mark {
  color: var(--f-ink);
}
.f12-checkbox-input:checked + .f12-checkbox-mark,
.f12-checkbox-input:indeterminate + .f12-checkbox-mark,
.f12-checkbox-input.f12-checkbox-indeterminate + .f12-checkbox-mark,
.f12-checkbox-input[data-indeterminate="true"] + .f12-checkbox-mark,
.f12-radio-input:checked + .f12-radio-mark {
  opacity: 1;
}

.f12-radio-group {
  border: 0;
  padding: 0;
  margin: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-family: var(--font-f-body);
  color: var(--f-ink);
}
.f12-radio-group.f12-radio-group-compact {
  gap: 6px;
}
.f12-radio-legend {
  padding: 0;
  margin-bottom: 6px;
}
.f12-radio-items {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.f12-radio-group.f12-radio-group-compact .f12-radio-items {
  gap: 6px;
}
.f12-radio-group.f12-radio-group-horizontal .f12-radio-items {
  flex-direction: row;
  flex-wrap: wrap;
  gap: 10px 18px;
}
.f12-radio-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.f12-switch {
  position: relative;
  display: inline-grid;
  flex: none;
  min-width: 54px;
  width: max-content;
  height: 28px;
}
.f12-switch.f12-switch-compact {
  min-width: 48px;
  height: 24px;
}
.f12-switch-input {
  position: absolute;
  inset: 0;
  z-index: 1;
  -webkit-appearance: none;
  appearance: none;
  margin: 0;
  width: 100%;
  height: 100%;
  background: var(--f-panel);
  border: var(--f-stroke) solid var(--f-rule);
  border-radius: 0;
  cursor: pointer;
  display: block;
}
.f12-switch-input.f12-switch-input-compact {
  border-width: 1.5px;
}
.f12-switch-input:checked {
  background: var(--f-ink);
}
.f12-switch-input:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-switch-input:disabled {
  cursor: not-allowed;
  border-style: dashed;
  opacity: 0.6;
}
.f12-switch-track {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 100%;
  pointer-events: none;
  display: inline-grid;
  align-items: center;
  overflow: hidden;
  background: var(--f-panel);
  border: var(--f-stroke) solid var(--f-rule);
  box-sizing: border-box;
}
.f12-switch-input.f12-switch-input-compact + .f12-switch-track {
  border-width: 1.5px;
}
.f12-switch-input:checked + .f12-switch-track {
  background: var(--f-ink);
}
.f12-switch-input:disabled + .f12-switch-track {
  border-style: dashed;
  opacity: 0.6;
}
.f12-switch-glyph {
  grid-area: 1 / 1;
  font-family: var(--font-f-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  line-height: 1;
  text-transform: uppercase;
  white-space: nowrap;
  user-select: none;
}
.f12-switch-glyph-on {
  justify-self: start;
  padding-inline-start: 4px;
  padding-inline-end: 22px;
  color: var(--f-panel);
  opacity: 0;
}
.f12-switch-glyph-off {
  justify-self: end;
  padding-inline-start: 22px;
  padding-inline-end: 4px;
  color: var(--f-ink-2);
  opacity: 1;
}
.f12-switch.f12-switch-compact .f12-switch-glyph-on {
  padding-inline-start: 4px;
  padding-inline-end: 20px;
}
.f12-switch.f12-switch-compact .f12-switch-glyph-off {
  padding-inline-start: 20px;
  padding-inline-end: 4px;
}
.f12-switch-input:checked + .f12-switch-track .f12-switch-glyph-on {
  opacity: 1;
}
.f12-switch-input:checked + .f12-switch-track .f12-switch-glyph-off {
  opacity: 0;
}
.f12-switch-thumb {
  position: absolute;
  top: 2px;
  bottom: 2px;
  width: 16px;
  inset-inline-start: 2px;
  background: var(--f-ink);
  border: 1.5px solid var(--f-rule);
}
.f12-switch.f12-switch-compact .f12-switch-thumb {
  top: 2px;
  bottom: 2px;
  width: 14px;
  inset-inline-start: 2px;
}
.f12-switch-input:checked + .f12-switch-track .f12-switch-thumb {
  inset-inline-start: calc(100% - 18px);
  background: var(--f-panel);
  border-color: var(--f-panel);
}
.f12-switch.f12-switch-compact .f12-switch-input:checked + .f12-switch-track .f12-switch-thumb {
  inset-inline-start: calc(100% - 16px);
}

.f12-tabs {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
  font-family: var(--font-f-body);
  color: var(--f-ink);
}
.f12-tabs.f12-tabs-compact {
  gap: 10px;
}
.f12-tabs.f12-tabs-vertical {
  flex-direction: row;
  align-items: flex-start;
  gap: 18px;
}
.f12-tabs-list {
  display: flex;
  flex-wrap: wrap;
  border: var(--f-stroke) solid var(--f-rule);
  background: var(--f-panel);
  width: fit-content;
  max-width: 100%;
  /* Breathing room when a block scrolls its section tabs into view (breadcrumb navigation). */
  scroll-margin-block-start: var(--f-gutter-scene);
}
.f12-tabs-list.f12-tabs-list-compact {
  border-width: 1.5px;
}
.f12-tabs.f12-tabs-vertical > .f12-tabs-list {
  flex-direction: column;
  flex: none;
}
.f12-tabs-trigger {
  flex: 1 1 auto;
  cursor: pointer;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 0;
  padding: 8px 16px;
  min-height: 36px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  line-height: 1.2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.f12-tabs-trigger + .f12-tabs-trigger {
  border-inline-start: 2px solid var(--f-rule);
}
.f12-tabs.f12-tabs-vertical > .f12-tabs-list .f12-tabs-trigger + .f12-tabs-trigger {
  border-inline-start: 0;
  border-top: 2px solid var(--f-rule);
}
.f12-tabs-list.f12-tabs-list-compact .f12-tabs-trigger {
  padding: 5px 12px;
  min-height: 28px;
  font-size: 11px;
}
.f12-tabs-list.f12-tabs-list-compact .f12-tabs-trigger + .f12-tabs-trigger {
  border-inline-start-width: 1.5px;
}
.f12-tabs.f12-tabs-vertical > .f12-tabs-list.f12-tabs-list-compact .f12-tabs-trigger + .f12-tabs-trigger {
  border-inline-start-width: 0;
  border-top-width: 1.5px;
}
.f12-tabs-trigger[aria-selected="true"] {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-tabs-trigger:disabled {
  cursor: not-allowed;
  color: var(--f-ink-2);
  opacity: 0.55;
}
.f12-tabs-trigger:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: -5px;
}
.f12-tabs-trigger[aria-selected="true"]:focus-visible {
  outline-color: var(--f-panel);
}
.f12-tabs-content {
  min-width: 0;
  flex: 1;
  width: 100%;
  --f12-autocut-display: none;
}
.f12-tabs-content[hidden] {
  display: none;
}
.f12-tabs-content .f12-cut[data-autocut] {
  display: none;
  counter-increment: none;
}
.f12-tabs-content:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}

/* ===================================================================== Alert, Notice, Toast, Skeleton, EmptyState, Breadcrumb & Pagination */
.f12-alert {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: var(--f-gutter-pair);
  padding: 14px 16px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  font-family: var(--font-f-body);
  min-width: 0;
}
.f12-alert-neutral {
  border: 1.5px solid var(--f-rule);
}
.f12-alert-info {
  border: 2px solid var(--f-rule);
}
.f12-alert-success {
  border: 2px solid var(--f-rule);
  border-inline-start: 6px solid var(--f-rule);
}
.f12-alert-warning {
  border: 2px dashed var(--f-rule);
  background-color: var(--f-panel);
  background-image: repeating-linear-gradient(
    -45deg,
    transparent 0 8px,
    var(--f-grid) 8px 9.5px
  );
}
.f12-alert-danger {
  border: 3px double var(--f-rule);
  border-inline-start: 6px solid var(--f-rule);
}
.f12-alert-glyph {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 6px;
  margin: 0;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--f-ink);
  background: var(--f-panel);
  border: 1.5px solid var(--f-rule);
}
.f12-alert-success .f12-alert-glyph {
  border-inline-start-width: 4px;
}
.f12-alert-warning .f12-alert-glyph {
  border-style: dashed;
}
.f12-alert-danger .f12-alert-glyph {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-alert-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.f12-alert-title {
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  line-height: 1.3;
  color: var(--f-ink);
  margin: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-alert-description {
  font-family: var(--font-f-body);
  font-size: 13px;
  line-height: 1.45;
  color: var(--f-ink);
  margin: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-alert-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
}
.f12-alert-dismiss {
  flex: none;
