  align-items: center;
  justify-content: center;
  min-width: 28px;
  min-height: 28px;
  padding: 2px 6px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 1.5px solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
}
.f12-alert-dismiss:hover {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-alert-dismiss:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-alert.f12-alert-compact {
  padding: 10px 12px;
}
.f12-alert.f12-alert-compact .f12-alert-title {
  font-size: 11px;
}
.f12-alert.f12-alert-compact .f12-alert-description {
  font-size: 12px;
}
.f12-alert.f12-alert-compact .f12-alert-dismiss {
  min-width: 24px;
  min-height: 24px;
}

.f12-toast-viewport {
  position: fixed;
  inset-inline-end: 20px;
  bottom: 20px;
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: var(--f-gutter-pair);
  width: min(380px, calc(100vw - 24px));
  max-width: 100%;
  max-height: calc(100vh - 32px);
  max-height: calc(100dvh - 32px);
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 0 6px 6px 0;
  box-sizing: border-box;
  pointer-events: auto;
  font-family: var(--font-f-body);
}
.f12-toast-viewport:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-toast-viewport:empty {
  display: none;
  pointer-events: none;
}
.f12-toast-viewport.f12-toast-viewport-compact {
  width: min(340px, calc(100vw - 24px));
}
@media (max-width: 480px) {
  .f12-toast-viewport,
  .f12-toast-viewport.f12-toast-viewport-compact {
    inset-inline-end: 12px;
    bottom: 12px;
    width: calc(100vw - 24px);
    max-height: calc(100vh - 24px);
    max-height: calc(100dvh - 24px);
  }
}
.f12-toast {
  pointer-events: auto;
  position: relative;
  flex-shrink: 0;
  display: flex;
  align-items: flex-start;
  gap: var(--f-gutter-pair);
  padding: 12px 14px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  box-shadow: 4px 4px 0 var(--f-rule);
  min-width: 0;
}
.f12-toast-neutral {
  border: 1.5px solid var(--f-rule);
}
.f12-toast-info {
  border: 2px solid var(--f-rule);
}
.f12-toast-success {
  border: 2px solid var(--f-rule);
  border-inline-start: 6px solid var(--f-rule);
}
.f12-toast-warning {
  border: 2px dashed var(--f-rule);
  background-color: var(--f-panel);
  background-image: repeating-linear-gradient(
    -45deg,
    transparent 0 8px,
    var(--f-grid) 8px 9.5px
  );
}
.f12-toast-danger {
  border: 3px double var(--f-rule);
  border-inline-start: 6px solid var(--f-rule);
}
.f12-toast-glyph {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 6px;
  margin: 0;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--f-ink);
  background: var(--f-panel);
  border: 1.5px solid var(--f-rule);
}
.f12-toast-success .f12-toast-glyph {
  border-inline-start-width: 4px;
}
.f12-toast-warning .f12-toast-glyph {
  border-style: dashed;
}
.f12-toast-danger .f12-toast-glyph {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-toast-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.f12-toast-title {
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  line-height: 1.3;
  color: var(--f-ink);
  margin: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-toast-description {
  font-family: var(--font-f-body);
  font-size: 13px;
  line-height: 1.4;
  color: var(--f-ink);
  margin: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-toast-controls {
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
}
.f12-toast-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 28px;
  min-width: 28px;
  padding: 4px 10px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 1.5px solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  line-height: 1.1;
  cursor: pointer;
}
.f12-toast-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  min-height: 28px;
  padding: 2px 6px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 1.5px solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
}
.f12-toast-action:hover,
.f12-toast-close:hover {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-toast-action:focus-visible,
.f12-toast-close:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-toast-queue-badge {
  pointer-events: auto;
  flex-shrink: 0;
  align-self: flex-end;
  padding: 3px 8px;
  background: var(--f-ink);
  color: var(--f-panel);
  border: 1.5px solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.f12-toast.f12-toast-compact {
  padding: 9px 12px;
  box-shadow: 3px 3px 0 var(--f-rule);
}
.f12-toast.f12-toast-compact .f12-toast-title {
  font-size: 11px;
}
.f12-toast.f12-toast-compact .f12-toast-description {
  font-size: 12px;
}
.f12-toast.f12-toast-compact .f12-toast-action,
.f12-toast.f12-toast-compact .f12-toast-close {
  min-height: 24px;
  min-width: 24px;
}

.f12-skeleton {
  position: relative;
  display: block;
  box-sizing: border-box;
  width: 100%;
  height: 20px;
  background-color: var(--f-panel);
  background-image: radial-gradient(circle, var(--f-tone) 1.15px, transparent 1.45px);
  background-size: 6px 6px;
  border: 1.5px dashed var(--f-rule);
  border-radius: 0;
}
.f12-skeleton-line {
  height: 14px;
  border-style: solid;
  border-width: 1px;
  border-color: var(--f-grid);
}
.f12-skeleton-circle {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  flex: none;
}
.f12-skeleton-metric {
  height: 44px;
  max-width: 180px;
  border: 2px solid var(--f-rule);
}
.f12-skeleton-panel {
  min-height: 120px;
  border: 2px dashed var(--f-rule);
}
.f12-skeleton.f12-skeleton-compact {
  height: 16px;
}
.f12-skeleton-line.f12-skeleton-compact {
  height: 12px;
}
.f12-skeleton-circle.f12-skeleton-compact {
  width: 28px;
  height: 28px;
}
.f12-skeleton-metric.f12-skeleton-compact {
  height: 32px;
}
.f12-skeleton-panel.f12-skeleton-compact {
  min-height: 88px;
}
.f12-skeleton-text {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}
.f12-skeleton-text.f12-skeleton-text-compact {
  gap: 6px;
}

.f12-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 10px;
  padding: 32px 20px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px dashed var(--f-rule);
  font-family: var(--font-f-body);
  min-width: 0;
}
.f12-empty.f12-empty-quiet {
  border: 1px solid var(--f-rule);
  padding: 24px 18px;
}
.f12-empty.f12-empty-compact {
  padding: 20px 16px;
  gap: 8px;
}
.f12-empty-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px 10px;
  font-family: var(--font-f-mono);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--f-ink);
  background-color: var(--f-panel);
  background-image: radial-gradient(circle, var(--f-tone) 1px, transparent 1.3px);
  background-size: 5px 5px;
  border: 1.5px solid var(--f-rule);
}
.f12-empty-code {
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.f12-empty-title {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: 22px;
  line-height: 1.15;
  letter-spacing: 0.02em;
  color: var(--f-ink);
  margin: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-empty.f12-empty-compact .f12-empty-title {
  font-size: 18px;
}
.f12-empty-description {
  font-family: var(--font-f-body);
  font-size: 13px;
  line-height: 1.45;
  color: var(--f-ink-2);
  max-width: 23.2em;
  margin: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-empty.f12-empty-compact .f12-empty-description {
  font-size: 12px;
}
.f12-empty-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--f-gutter-pair);
  margin-top: 6px;
}

.f12-breadcrumb {
  display: block;
  font-family: var(--font-f-mono);
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  min-width: 0;
}
.f12-breadcrumb-list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 8px;
  list-style: none;
  padding: 0;
  margin: 0;
}
.f12-breadcrumb-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.f12-breadcrumb-link {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 2px 4px;
  color: var(--f-ink-2);
  /* Non-colour cue: actionable crumbs and plain ancestor text share --f-ink-2 (WCAG 1.4.1). */
  text-decoration: underline dotted 1px;
  text-underline-offset: 3px;
  cursor: pointer;
}
.f12-breadcrumb-link:hover {
  color: var(--f-ink);
  text-decoration-style: solid;
}
/* <BreadcrumbButton>: in-page action crumb rendered with link chrome. */
button.f12-breadcrumb-link {
  appearance: none;
  margin: 0;
  border: 0;
  border-radius: 0;
  background: none;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  text-align: inherit;
}
.f12-breadcrumb-link:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
  color: var(--f-ink);
}
.f12-breadcrumb-page {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 2px 6px;
  font-weight: 700;
  color: var(--f-ink);
  border-bottom: 2px solid var(--f-rule);
}
.f12-breadcrumb-page:not([aria-current]) {
  font-weight: 500;
  color: var(--f-ink-2);
  border-bottom: 0;
}
.f12-breadcrumb-separator {
  display: inline-flex;
  align-items: center;
  color: var(--f-ink-2);
  user-select: none;
}
.f12-breadcrumb-ellipsis {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  min-height: 24px;
  padding: 0 4px;
  color: var(--f-ink-2);
  border: 1px dashed var(--f-rule);
}
.f12-breadcrumb.f12-breadcrumb-compact {
  font-size: 10px;
}
.f12-breadcrumb.f12-breadcrumb-compact .f12-breadcrumb-list {
  gap: 2px 6px;
}
/* Sheet header: give the path its own line above the eyebrow (the current-item rule otherwise
   lands on the eyebrow tags) and pull the first crumb's padding back onto the text edge. */
.f12-hd-text > .f12-breadcrumb:not(:last-child) {
  margin-bottom: 14px;
}
.f12-hd-text > .f12-breadcrumb .f12-breadcrumb-item:first-child > .f12-breadcrumb-link {
  margin-inline-start: -4px;
}
.f12-hd-text > .f12-breadcrumb .f12-breadcrumb-item:first-child > .f12-breadcrumb-page {
  margin-inline-start: -6px;
}

.f12-pagination {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--f-gutter-pair);
  font-family: var(--font-f-mono);
  color: var(--f-ink);
  min-width: 0;
}
.f12-pagination-summary {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: var(--f-ink-2);
}
.f12-pagination-list {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  list-style: none;
  padding: 0;
  margin: 0;
}
.f12-pagination-item {
  display: inline-flex;
  align-items: center;
}
.f12-pagination-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 34px;
  min-height: 34px;
  padding: 6px 10px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  box-sizing: border-box;
}
.f12-pagination-link:hover:not(:disabled):not([aria-disabled="true"]):not(.f12-pagination-link-active) {
  box-shadow: 2px 2px 0 var(--f-rule);
}
.f12-pagination-link:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-pagination-link-active,
.f12-pagination-link[aria-current="page"] {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-pagination-link:disabled,
.f12-pagination-link-disabled,
.f12-pagination-link[aria-disabled="true"] {
  cursor: not-allowed;
  border-style: dashed;
  color: var(--f-ink-2);
  opacity: 0.6;
  box-shadow: none;
}
.f12-pagination-prev,
.f12-pagination-next {
  padding: 6px 12px;
}
.f12-pagination-arrow {
  font-size: 14px;
  line-height: 1;
}
.f12-pagination-ellipsis {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  min-height: 34px;
  padding: 0 4px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  color: var(--f-ink-2);
  user-select: none;
}
.f12-pagination.f12-pagination-compact .f12-pagination-list {
  gap: 4px;
}
.f12-pagination-link.f12-pagination-link-compact,
.f12-pagination.f12-pagination-compact .f12-pagination-link {
  min-width: 28px;
  min-height: 28px;
  padding: 4px 8px;
  font-size: 11px;
  border-width: 1.5px;
}
.f12-pagination.f12-pagination-compact .f12-pagination-ellipsis {
  min-width: 24px;
  min-height: 28px;
  font-size: 11px;
}

/* ===================================================================== Metric, Delta & Spark */
.f12-metric {
  display: flex;
  flex-direction: column;
  flex: 1;
}
.f12-m-label {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  margin: 0;
}
.f12-m-value {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: 34px;
  line-height: 1.22;
  padding-bottom: 2px;
  margin: 10px 0 0;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
  color: var(--f-ink);
}
/* Expressive hero: sized to its own column, not the sheet. --f12-m-chars (set by <Metric> from
   the final formatted value) and ~0.8em per display-font glyph keep the longest value inside
   its panel; 14cqi caps short values so they don't balloon in wide columns. */
.f12-metric.big {
  container-type: inline-size;
  min-width: min(100%, 12rem);
}
.f12-metric.big .f12-m-value {
  font-size: clamp(20px, min(14cqi, 100cqi / (var(--f12-m-chars, 8) * 0.8)), 56px);
  line-height: 1.1;
  font-variant-numeric: proportional-nums;
  overflow-wrap: anywhere;
}
.f12-metric.f12-metric-quiet .f12-m-value {
  font-family: var(--font-f-mono);
  font-weight: 700;
  font-size: 22px;
  line-height: 1.2;
  margin-top: 6px;
  letter-spacing: -0.01em;
  font-variant-numeric: tabular-nums;
}
.f12-metric.f12-metric-quiet .f12-delta {
  margin-top: 8px;
  font-size: 11px;
}
.f12-metric.f12-metric-quiet .f12-m-note {
  font-size: 12px;
  margin-top: 4px;
}
.f12-delta {
  display: flex;
  align-items: baseline;
  gap: 6px;
  flex-wrap: wrap;
  font-variant-numeric: tabular-nums;
  font-family: var(--font-f-mono);
  font-size: 12px;
  margin: 14px 0 0;
  letter-spacing: 0.02em;
  color: var(--f-ink);
}
.f12-delta-sym {
  font-size: 10px;
}
.f12-delta.up .f12-delta-sym,
.f12-delta.down .f12-delta-sym {
  color: var(--f-marker-ink);
  background: var(--f-marker);
  padding: 0 3px;
}
.f12-delta-ref {
  color: var(--f-ink-2);
}
.f12-m-note {
  font-size: 13px;
  color: var(--f-ink-2);
  margin: 6px 0 0;
  max-width: 15.1em;
}

.f12-spark {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: auto;
  padding-top: 16px;
}
.f12-spark svg {
  display: block;
  width: 100%;
  border-bottom: 2px solid var(--f-rule);
  overflow: visible;
}
.f12-spark-l {
  font-family: var(--font-f-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  margin: 0;
}
.f12-spark-bar {
  stroke: var(--f-ink);
  stroke-width: 1;
}

/* ===================================================================== Chart, Balloon & Data Table */
.f12-c01-hd {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: flex-end;
  gap: 12px 24px;
  margin-bottom: 4px;
}
.f12-c01-hd > .f12-metric {
  flex: 1 1 220px;
}
.f12-legend,
.f12-legend-hint {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  letter-spacing: 0.04em;
  color: var(--f-ink-2);
  margin: 0;
  padding: 0;
  list-style: none;
}
.f12-legend li {
  display: flex;
  align-items: center;
  gap: 6px;
}
.f12-legend-hint {
  max-width: 13em;
}
.f12-sw {
  display: inline-block;
  width: 14px;
  height: 0;
  border-top-width: 2px;
  border-top-style: solid;
  flex: none;
}
.f12-sw-total {
  border-color: var(--f-ink);
  border-top-width: var(--f-stroke);
}
.f12-sw-focus {
  border-color: var(--f-ink);
  border-top-style: dashed;
}

.f12-chart {
  position: relative;
  width: 100%;
  touch-action: pan-y;
}
.f12-chart-svg {
  display: block;
  width: 100%;
  overflow: visible;
}
.f12-chart-svg:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 4px;
}
.f12-chart text {
  fill: var(--f-ink-2);
  font-family: var(--font-f-mono);
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
}
.f12-grid {
  stroke: var(--f-grid);
}
.f12-baseline {
  stroke: var(--f-rule);
  stroke-width: 2;
}
.f12-sheet-ticks line {
  stroke: var(--f-rule);
  stroke-width: 1;
}
.f12-tone-dot {
  fill: var(--f-tone);
}
.f12-l-total {
  stroke: var(--f-ink);
  stroke-width: var(--f-stroke);
  stroke-linejoin: round;
  stroke-linecap: round;
}
.f12-l-focus {
  stroke: var(--f-ink);
  stroke-width: 2;
  stroke-dasharray: 6 4;
  stroke-linejoin: round;
}
.f12-tail {
  fill: var(--f-panel);
  stroke: var(--f-rule);
  stroke-width: 2;
  stroke-linejoin: miter;
}
.f12-g-tag {
  fill: var(--f-marker);
}
.f12-peak-dot {
  fill: var(--f-marker);
  stroke: var(--f-rule);
  stroke-width: 2;
}
.f12-balloon {
  position: absolute;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  max-width: calc(100% - 60px);
  min-width: 0;
  padding: 3px 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  border-radius: 14px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-balloon-gap {
  position: absolute;
  /* Centred default (tail offset 0); <Balloon> sets the exact offset inline. */
  left: calc(50% - 5px);
  bottom: -2px;
  width: 10px;
  height: 3px;
  background: var(--f-panel);
}
.f12-balloon-standalone {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  max-width: 100%;
  min-width: 0;
}
.f12-balloon-standalone .f12-balloon {
  position: relative;
  max-width: 100%;
  min-height: 28px;
}
.f12-balloon-standalone-svg {
  display: block;
  overflow: visible;
  margin-top: -1px;
}

.f12-cross line {
  stroke: var(--f-ink);
  stroke-width: 1;
}
.f12-cross-dot {
  fill: var(--f-marker);
  stroke: var(--f-rule);
  stroke-width: 2;
}
.f12-compare-pt,
.f12-cross-dot2 {
  fill: var(--f-panel);
  stroke: var(--f-rule);
  stroke-width: 2;
}
.f12-tip {
  position: absolute;
  z-index: 3;
  pointer-events: none;
  display: grid;
  gap: 2px;
  min-width: 160px;
  padding: 8px 10px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  background: var(--f-panel);
  border: 2px solid var(--f-rule);
  color: var(--f-ink);
  font-family: var(--font-f-mono);
  box-shadow: 4px 4px 0 var(--f-rule);
}
.f12-tip span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.f12-tbl {
  margin-top: 10px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  color: var(--f-ink);
}
.f12-tbl summary {
  cursor: pointer;
  width: fit-content;
  max-width: 100%;
  padding: 4px 0;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.f12-tbl-scroll {
  max-height: 240px;
  overflow: auto;
  margin-top: 6px;
}
.f12-tbl table {
  border-collapse: collapse;
  width: 100%;
  font-variant-numeric: tabular-nums;
}
.f12-tbl th,
.f12-tbl td {
  text-align: left;
  padding: 5px 10px 5px 0;
  white-space: nowrap;
}
.f12-tbl th {
  color: var(--f-ink-2);
  font-weight: 500;
  border-bottom: 2px solid var(--f-rule);
}
.f12-tbl td {
  border-bottom: 1px solid var(--f-grid);
}

/* ===================================================================== ToneBarList (Interventions) */
.f12-ints-hd {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: baseline;
  gap: 6px 16px;
  margin-bottom: 14px;
}
.f12-ints-sub {
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink-2);
  letter-spacing: 0.04em;
  margin: 0;
}
.f12-ints-list {
  display: grid;
  list-style: none;
  padding: 0;
  margin: 0;
}
.f12-ints-list li + li {
  border-top: 1px solid var(--f-grid);
}
.f12-int-row {
  all: unset;
  box-sizing: border-box;
  cursor: pointer;
  display: grid;
  width: 100%;
  align-items: center;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 2fr) auto;
  gap: 16px;
  padding: 12px 8px;
  color: var(--f-ink);
}
.f12-int-row:hover .f12-int-name {
  text-decoration: underline;
  text-underline-offset: 3px;
}
.f12-int-row:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: -3px;
}
.f12-int-name {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex-wrap: wrap;
  font-size: 15px;
  font-weight: 700;
}
.f12-int-bar {
  position: relative;
  display: block;
  height: 16px;
  border: 2px solid var(--f-rule);
}
.f12-int-fill {
  position: absolute;
  inset: 0 auto 0 0;
  background-image: radial-gradient(circle, var(--f-tone) 1.1px, transparent 1.4px);
  background-size: 5px 5px;
  border-right: 2px solid var(--f-rule);
}
.f12-int-fill-hatch {
  background-image: repeating-linear-gradient(
    -45deg,
    var(--f-tone) 0,
    var(--f-tone) 1.25px,
    transparent 1.25px,
    transparent 5px
  );
  background-size: auto;
}
.f12-int-fill-dense {
  background-image: radial-gradient(circle, var(--f-tone) 1.55px, transparent 1.85px);
  background-size: 4px 4px;
}
.f12-ints.f12-ints-compact .f12-int-row {
  padding: 7px 6px;
  gap: 12px;
}
.f12-ints.f12-ints-compact .f12-int-name {
  font-size: 13px;
}
.f12-ints.f12-ints-compact .f12-int-bar {
  height: 12px;
  border-width: 1.5px;
}
.f12-int-row[aria-pressed="true"],
.f12-int-row[aria-current="true"] {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-int-row[aria-pressed="true"]:focus-visible {
  outline-color: var(--f-panel);
}
.f12-int-row[aria-pressed="true"] .f12-int-bar,
.f12-int-row[aria-current="true"] .f12-int-bar {
  border-color: var(--f-panel);
}
.f12-int-row[aria-pressed="true"] .f12-int-fill,
.f12-int-row[aria-current="true"] .f12-int-fill {
  background: var(--f-marker);
  border-right-color: var(--f-panel);
}
.f12-int-row[aria-pressed="true"] .f12-int-share,
.f12-int-row[aria-current="true"] .f12-int-share {
  color: var(--f-panel);
}
.f12-int-row[aria-pressed="true"] .f12-badge,
.f12-int-row[aria-current="true"] .f12-badge {
  border-color: var(--f-panel);
}
/* Non-interactive rows (rendered by @frame12/static): same layout, no pointer affordance. */
.f12-int-row[data-static] {
  cursor: default;
}
.f12-int-row[data-static]:hover .f12-int-name {
  text-decoration: none;
}
.f12-int-val {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  font-family: var(--font-f-mono);
  font-size: 13px;
  font-weight: 500;
}
.f12-int-share {
  min-width: 3ch;
  text-align: right;
  color: var(--f-ink-2);
}

/* ===================================================================== Adapters: Dialog, Select, Tooltip, DropdownMenu, Table */

/* Dialog */
dialog.f12-dialog {
  margin: auto;
  background: var(--f-panel);
  color: var(--f-ink);
  border: var(--f-stroke) solid var(--f-rule);
  box-shadow: 6px 6px 0 var(--f-rule);
  padding: 34px 22px 22px;
  max-width: 480px;
  width: calc(100% - 32px);
  font-family: var(--font-f-body);
}
dialog.f12-dialog:modal {
  overscroll-behavior: contain;
}
dialog.f12-dialog::backdrop {
  overflow: hidden;
  overscroll-behavior: contain;
  background-color: var(--f-backdrop);
  background-image: radial-gradient(circle, rgba(18, 18, 18, 0.35) 0.85px, transparent 1.35px);
  background-size: 8px 8px;
}
dialog.f12-dialog > .f12-cut {
  top: 8px;
  left: 22px;
  padding: 1px 6px;
  background: var(--f-sheet);
  border: 1.5px solid var(--f-rule);
}
.f12-dialog-header {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}
.f12-dialog-title {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: 24px;
  line-height: 1.1;
  color: var(--f-ink);
  margin: 0;
}
.f12-dialog-description {
  font-size: 14px;
  color: var(--f-ink-2);
  margin: 0;
}
.f12-dialog-footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--f-gutter-pair);
  margin-top: 20px;
}

/* Select */
.f12-select {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  gap: 6px;
  min-width: 180px;
  font-family: var(--font-f-body);
}
.f12-select-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--f-gutter-pair);
  width: 100%;
  padding: 8px 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: var(--f-stroke) solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  text-align: left;
}
.f12-select-trigger:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-select.f12-select-compact {
  gap: 4px;
}
.f12-select.f12-select-compact .f12-select-trigger {
  padding: 6px 10px;
  font-size: 13px;
  line-height: 1.4;
  border-width: 1.5px;
}
.f12-select-caret {
  display: inline-block;
  padding: 1px 4px;
  font-size: 10px;
  background: var(--f-marker);
  color: var(--f-marker-ink);
  border: 1.5px solid var(--f-rule);
  line-height: 1;
}
.f12-select-content {
  z-index: 50;
  min-width: var(--radix-select-trigger-width, 180px);
  max-height: var(--radix-select-content-available-height, 300px);
  overflow-y: auto;
  background: var(--f-panel);
  color: var(--f-ink);
  border: var(--f-stroke) solid var(--f-rule);
  box-shadow: 4px 4px 0 var(--f-rule);
  list-style: none;
  margin: 0;
  padding: 0;
}
.f12-select-viewport {
  padding: 0;
}
.f12-select-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 8px 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 0;
  border-bottom: 1px solid var(--f-grid);
  font-family: var(--font-f-mono);
  font-size: 12px;
  cursor: pointer;
  text-align: left;
  user-select: none;
}
.f12-select-item:last-child {
  border-bottom: 0;
}
.f12-select-item:hover,
.f12-select-item[data-highlighted],
.f12-select-item[aria-selected="true"],
.f12-select-item[data-state="checked"] {
  background: var(--f-ink);
  color: var(--f-panel);
  outline: none;
}
.f12-select-item:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: -3px;
}
.f12-select-item[data-highlighted]:focus-visible,
.f12-select-item[aria-selected="true"]:focus-visible,
.f12-select-item[data-state="checked"]:focus-visible {
  outline: 2px solid var(--f-panel);
  outline-offset: -4px;
}
.f12-select-item[data-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}
.f12-select-check {
  background: var(--f-marker);
  color: var(--f-marker-ink);
  padding: 0 4px;
  font-size: 10px;
  font-weight: 700;
}
.f12-select-label {
  padding: 6px 12px 4px;
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.f12-select-sep {
  height: 1px;
  background: var(--f-grid);
  margin: 4px 0;
}

/* Tooltip */
.f12-tooltip-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}
.f12-tooltip {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  z-index: 50;
  white-space: nowrap;
  padding: 5px 10px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  box-shadow: 3px 3px 0 var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 11px;
  pointer-events: none;
}

/* DropdownMenu */
.f12-menu-wrap {
  position: relative;
  display: inline-block;
}
.f12-menu {
  z-index: 50;
  min-width: 180px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: var(--f-stroke) solid var(--f-rule);
  box-shadow: 4px 4px 0 var(--f-rule);
  padding: 4px 0;
}
.f12-menu-label {
  padding: 6px 12px 4px;
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.f12-menu-sep {
  height: 1px;
  background: var(--f-grid);
  margin: 4px 0;
}
.f12-menu-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 7px 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 0;
  font-family: var(--font-f-body);
  font-size: 13px;
  cursor: pointer;
  text-align: left;
  user-select: none;
}
.f12-menu-item:hover,
.f12-menu-item[data-highlighted],
.f12-menu-item:focus-visible {
  background: var(--f-ink);
  color: var(--f-panel);
  outline: none;
}
.f12-menu-item:focus-visible {
  outline: 2px solid var(--f-panel);
  outline-offset: -4px;
}
.f12-menu-item[data-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Table */
.f12-table-wrap {
  width: 100%;
  overflow-x: auto;
}
.f12-table-wrap:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-table {
  width: 100%;
  border-collapse: collapse;
  font-family: var(--font-f-body);
  font-size: 13px;
  color: var(--f-ink);
  font-variant-numeric: tabular-nums;
}
.f12-table caption {
  caption-side: bottom;
  padding-top: 8px;
  text-align: left;
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink-2);
}
.f12-table th,
.f12-table td {
  text-align: left;
  padding: 8px 12px 8px 0;
  border-bottom: 1px solid var(--f-grid);
}
.f12-table thead th {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  border-bottom: var(--f-stroke) solid var(--f-rule);
}
.f12-table tfoot td,
.f12-table tfoot th {
  font-family: var(--font-f-mono);
  font-weight: 700;
  border-top: 2px solid var(--f-rule);
  border-bottom: 0;
}
.f12-table.f12-table-compact {
  font-size: 13px;
}
.f12-table.f12-table-compact th,
.f12-table.f12-table-compact td {
  padding: 5px 10px 5px 0;
}
.f12-table.f12-table-compact thead th {
  border-bottom-width: 1.5px;
}

/* ===================================================================== Application Block & Layout Utilities */
.f12-stack-pair {
  display: flex;
  flex-direction: column;
  gap: var(--f-gutter-pair);
  min-width: 0;
}
.f12-stack-scene {
  display: flex;
  flex-direction: column;
  gap: var(--f-gutter-scene);
  min-width: 0;
}
.f12-row-pair {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--f-gutter-pair);
}
.f12-row-between {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--f-gutter-pair) var(--f-gutter-scene);
}
.f12-section-title {
  margin: 0;
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: clamp(20px, 3vw, 28px);
  line-height: 1.1;
  color: var(--f-ink);
}
.f12-body-copy {
  margin: 0;
  font-size: 15px;
  line-height: 1.55;
  color: var(--f-ink);
  max-width: 34.25em;
}
.f12-muted-copy {
  margin: 0;
  font-size: 14px;
  line-height: 1.5;
  color: var(--f-ink-2);
  max-width: 33.25em;
}
.f12-mono-note {
  margin: 0;
  font-family: var(--font-f-mono);
  font-size: 13px;
  line-height: 1.5;
  color: var(--f-ink-2);
}
.f12-code-inline {
  font-family: var(--font-f-mono);
  font-size: 0.92em;
  padding: 1px 5px;
  border: 1px solid var(--f-grid);
  background-color: var(--f-sheet);
  color: var(--f-ink);
  overflow-wrap: anywhere;
}
.f12-nowrap {
  white-space: nowrap;
}

.f12-console .f12-hd > .f12-hd-text {
  flex: 1 1 540px;
}
.f12-console .f12-sub {
  max-width: 64ch;
  font-size: 13px;
  line-height: 1.5;
  margin-top: 6px;
}
.f12-console-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--f-gutter-pair) var(--f-gutter-scene);
  min-width: 0;
}
/* Sheet-header toolbar: sit the environment Select beside the range SegmentedControl at the
   same 44px height and rule weight, packed left like the other blocks' header control rows. */
.f12-console-hd-toolbar {
  justify-content: flex-start;
}
.f12-console-hd-toolbar .f12-select-trigger {
  min-height: 44px;
}
.f12-console-filters {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: var(--f-gutter-pair);
  align-items: end;
  min-width: 0;
}
.f12-console-grid-2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--f-gutter-pair);
  min-width: 0;
}
.f12-console .f12-int-row {
  grid-template-columns: minmax(220px, 1.75fr) minmax(52px, 1fr) minmax(0, auto);
  gap: var(--f-gutter-pair);
}
.f12-console .f12-int-name {
  font-size: 13px;
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.f12-console .f12-int-val {
  font-size: 13px;
  min-width: 0;
}
.f12-console-kpi-scene > .f12-panel > .f12-panel-body {
  padding: 20px 18px 16px;
}
.f12-console-kpi-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: var(--f-gutter-pair);
  height: 100%;
  min-width: 0;
}
.f12-console-kpi-card .f12-m-value {
  margin-top: 4px;
  line-height: 1.08;
}
.f12-console-kpi-card .f12-delta {
  margin-top: 8px;
  font-size: 12.5px;
}
.f12-console-kpi-spark {
  margin-top: auto;
}
.f12-console-kpi-spark .f12-spark {
  margin-top: 0;
  padding-top: 4px;
}
.f12-console-kpi-spark .f12-spark-l {
  font-size: 11px;
  line-height: 1.35;
  letter-spacing: 0.1em;
}
.f12-console-kpi-spark .f12-spark svg {
  height: 38px;
}
.f12-console-kv-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: var(--f-gutter-pair);
  margin: 0;
  min-width: 0;
}
.f12-console-kv-list.f12-console-kpi-foot {
  margin-top: auto;
