'use client';

import * as React from 'react';
import { useReducedMotion, useResolvedMotion } from '@/hooks/use-tempo';

export type MotionMode = 'stepped' | 'smooth' | 'cut';

export const FRAME_MS = 1000 / 12; // animating "on twos": 12 drawings per second (83.33ms per pose)

const easeOut = (t: number): number => 1 - Math.pow(1 - t, 3);

const useIsoLayoutEffect = typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect;

export function useSize(ref: { readonly current: HTMLElement | null }): { w: number; h: number } {
  const [size, setSize] = React.useState<{ w: number; h: number }>({ w: 0, h: 0 });

  useIsoLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    // Layout size (offsetWidth/Height), not the transformed box, so scaled previews draw correctly.
    const measure = () => {
      const w = el.offsetWidth;
      const h = el.offsetHeight;
      setSize((s) => (s.w === w && s.h === h ? s : { w, h }));
    };
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [ref]);

  return size;
}

// Re-exported so existing `import { useReducedMotion } from '@/hooks/use-on-twos'` keeps working.
export { useReducedMotion };

/**
 * Progress 0..1 that replays whenever `key` changes.
 *
 * Stepped mode samples the cubic-out easing curve at 12 poses per second
 * (`FRAME_MS = 1000 / 12 = 83.33ms` per pose), like an animation exposure sheet
 * ("on twos"). Pose 1 (`k = 1`, `t = 1 / frames`) is displayed immediately at
 * `elapsed = 0` (`Math.floor(el / FRAME_MS) + 1`) so the element visibly steps
 * on the exact interaction frame rather than sitting at 0 for 83.33ms, and each
 * subsequent pose is held for a full 83.33ms interval until `frames` poses complete.
 *
 * Only changes to `key` trigger a new tween; changing `duration` or `motion`
 * alone keeps the current resting state. `motion` is resolved against the nearest
 * TempoProvider and the OS (`resolveMotion` in use-tempo.ts): `prefers-reduced-motion: reduce`
 * and a `still` tempo always cut; a change to `'cut'` mid-tween settles immediately.
 */
export function useOnTwos(
  key: unknown,
  duration = 600,
  motion: MotionMode = 'stepped',
): number {
  const effectiveMotion: MotionMode = useResolvedMotion(motion);
  const [p, setP] = React.useState<number>(1);
  const prevKeyRef = React.useRef<unknown>(key);
  const frames = Math.max(2, Math.round(duration / FRAME_MS));
  const initialP =
    effectiveMotion === 'cut' ? 1 : effectiveMotion === 'stepped' ? easeOut(1 / frames) : 0;

  useIsoLayoutEffect(() => {
    if (effectiveMotion === 'cut') {
      prevKeyRef.current = key;
      setP(1);
      return;
    }
    if (Object.is(prevKeyRef.current, key)) {
      setP(1);
      return;
    }
    prevKeyRef.current = key;
    const start = performance.now();
    const totalFrames = Math.max(2, Math.round(duration / FRAME_MS));
    let raf = 0;
    let last = -1;
    const tick = (now: number) => {
      const el = now - start;
      let t: number;
      if (effectiveMotion === 'stepped') {
        const k = Math.min(totalFrames, Math.floor(el / FRAME_MS) + 1);
        t = k / totalFrames;
      } else {
        t = Math.min(1, el / duration);
      }
      const v = easeOut(t);
      if (v !== last) {
        last = v;
        setP(v);
      }
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    setP(effectiveMotion === 'stepped' ? easeOut(1 / totalFrames) : 0);
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [key, duration, effectiveMotion]);

  const isNewKey = !Object.is(prevKeyRef.current, key);
  return isNewKey ? initialP : p;
}

export const useTween = useOnTwos;

export function useCountUp(
  value: number,
  motion: MotionMode = 'stepped',
  duration = 600,
): number {
  const prev = React.useRef<number>(value);
  const from = React.useRef<number>(value);
  const displayedRef = React.useRef<number>(value);
  if (!Object.is(prev.current, value)) {
    from.current = displayedRef.current;
    prev.current = value;
  }
  const p = useOnTwos(value, duration, motion);
  const current = from.current + (value - from.current) * p;
  displayedRef.current = current;
  return current;
}

/**
 * Becomes true after the first change of `key`, so entrance animations
 * never run on first paint (the page is complete at rest).
 */
export function useChanged(key: unknown): boolean {
  const first = React.useRef<unknown>(key);
  const [changed, setChanged] = React.useState<boolean>(false);
  React.useEffect(() => {
    if (key !== first.current) setChanged(true);
  }, [key]);
  return changed;
}

'use client';

import * as React from 'react';

// Same union as `MotionMode` in use-on-twos.ts. Declared locally (not imported) so this module has
// no dependencies: use-on-twos.ts imports from here, never the other way round.
type MotionMode = 'stepped' | 'smooth' | 'cut';

/**
 * The viewer's animation tempo.
 *
 * | Tempo   | Label | Meaning                                                              |
 * |---------|-------|----------------------------------------------------------------------|
 * | `auto`  | AUTO  | each component's own intended motion (default)                        |
 * | `twos`  | 12    | on twos: held poses, 12 per second                                    |
 * | `ones`  | 60    | smooth, continuous motion (follows the display's refresh rate)        |
 * | `still` | 0     | no non-essential motion                                               |
 */
export type Tempo = 'auto' | 'twos' | 'ones' | 'still';

export const TEMPOS: readonly Tempo[] = ['auto', 'twos', 'ones', 'still'];

export function isTempo(value: unknown): value is Tempo {
  return value === 'auto' || value === 'twos' || value === 'ones' || value === 'still';
}

/** Any invalid runtime value (a stored `"fast"`, `null`, a number) is treated as `auto`. */
export function normalizeTempo(value: unknown): Tempo {
  return isTempo(value) ? value : 'auto';
}

export interface ResolveMotionInput {
  /** The component's `motion` prop, otherwise its own default (`Metric` quiet → `'cut'`). Undefined means `'stepped'`. */
  base?: MotionMode;
  /** The nearest provider's tempo. Invalid values are treated as `auto`. */
  tempo?: Tempo;
  /** True when any provider above the nearest one is `still`. */
  ancestorStill?: boolean;
  /** The OS `prefers-reduced-motion: reduce` preference. */
  reduced?: boolean;
}

/**
 * Resolves the motion a component actually plays. Rules, in order:
 *   1. OS reduced motion → `'cut'`.
 *   2. `still` here or in any ancestor → `'cut'`.
 *   3. `base === 'cut'` → `'cut'`: tempo never turns motion on where a component, a variant or an
 *      explicit prop says none.
 *   4. `twos` → `'stepped'`; `ones` → `'smooth'`.
 *   5. `auto` → `base`.
 * Direct manipulation (pointer tracking, drag, scroll, typing, focus movement) never goes through
 * this: it is never stepped or delayed, at any tempo.
 */
export function resolveMotion({
  base,
  tempo,
  ancestorStill = false,
  reduced = false,
}: ResolveMotionInput): MotionMode {
  if (reduced) return 'cut';
  const t = normalizeTempo(tempo);
  if (t === 'still' || ancestorStill) return 'cut';
  const b: MotionMode = base === undefined ? 'stepped' : base;
  if (b === 'cut') return 'cut';
  if (t === 'twos') return 'stepped';
  if (t === 'ones') return 'smooth';
  return b;
}

export interface TempoContextValue {
  /** The nearest provider's tempo (`auto` without a provider). */
  tempo: Tempo;
  /** Sets the nearest provider's tempo. A no-op without a provider. */
  setTempo: (tempo: Tempo) => void;
  /** True when a provider above the nearest one is `still` (it cannot be undone below). */
  ancestorStill: boolean;
  /** False when no TempoProvider is above this point. */
  inProvider: boolean;
}

const NO_PROVIDER: TempoContextValue = {
  tempo: 'auto',
  setTempo: () => {},
  ancestorStill: false,
  inProvider: false,
};

export const TempoContext = React.createContext<TempoContextValue>(NO_PROVIDER);
TempoContext.displayName = 'TempoContext';

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

function subscribeReducedMotion(onStoreChange: () => void): () => void {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    return () => {};
  }
  const q = window.matchMedia(REDUCED_MOTION_QUERY);
  if (q.addEventListener) {
    q.addEventListener('change', onStoreChange);
    return () => q.removeEventListener('change', onStoreChange);
  }
  q.addListener(onStoreChange);
  return () => q.removeListener(onStoreChange);
}

function getReducedMotionSnapshot(): boolean {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    return false;
  }
  return window.matchMedia(REDUCED_MOTION_QUERY).matches;
}

function getReducedMotionServerSnapshot(): boolean {
  return false;
}

/** The OS `prefers-reduced-motion: reduce` preference. Without `matchMedia`, false. */
export function useReducedMotion(): boolean {
  return React.useSyncExternalStore(
    subscribeReducedMotion,
    getReducedMotionSnapshot,
    getReducedMotionServerSnapshot,
  );
}

export interface TempoState extends TempoContextValue {
  /** The OS reduced-motion preference. */
  reduced: boolean;
  /** What actually applies here: `still` when reduced motion or an ancestor forces it. */
  effectiveTempo: Tempo;
}

/** The tempo at this point in the tree, plus what actually applies after the OS and ancestors. */
export function useTempo(): TempoState {
  const ctx = React.useContext(TempoContext);
  const reduced = useReducedMotion();
  return React.useMemo(
    () => ({ ...ctx, reduced, effectiveTempo: reduced || ctx.ancestorStill ? 'still' : ctx.tempo }),
    [ctx, reduced],
  );
}

/** The motion a component with this `base` should play here (see `resolveMotion`). */
export function useResolvedMotion(base?: MotionMode): MotionMode {
  const { tempo, ancestorStill } = React.useContext(TempoContext);
  const reduced = useReducedMotion();
  return resolveMotion({ base, tempo, ancestorStill, reduced });
}
